package cn.mop.api;
import cn.mop.domain.*;
import cn.mop.domain.assetexport.*;
import cn.mop.domain.assetexport.AssetExportJobRepository.*;
import cn.mop.domain.assetexport.AssetExportJobState.*;
import cn.mop.domain.assetexport.AssetExportPublicationRepository.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.env.MockEnvironment;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.Instant;
import java.util.*;
import java.util.function.Supplier;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class AssetExportPublicationControllerTest {
    @Test void springWiringSelectsPublicationAdapterWhenJobRepositoryImplementsBothInterfaces(){
        try(var context=new org.springframework.context.annotation.AnnotationConfigApplicationContext()){
            context.getEnvironment().setActiveProfiles("remote_test");
            context.registerBean("assetExportJobRepository",AssetExportJobRepository.class,()->mock(AssetExportJobRepository.class,withSettings().extraInterfaces(AssetExportPublicationRepository.class)));
            context.registerBean(PlatformRepository.class,()->mock(PlatformRepository.class));
            context.register(AssetExportPublicationConfiguration.class,AssetExportPublicationController.class);context.refresh();assertNotNull(context.getBean(AssetExportPublicationController.class));
        }
    }
    final String actor="7f000000-0000-4000-8000-000000000001",tenant="7f000000-0000-4000-8000-000000000002",id="7f000000-0000-4000-8000-000000000003";
    final Instant now=Instant.parse("2026-10-14T00:00:00Z");final byte[] bytes="SYNTHETIC_EXPORT_TEST".getBytes(StandardCharsets.UTF_8);
    PlatformRepository platform;AssetExportPublicationRepository publications;AssetExportObjectStore store;AssetExportDownloadGrant grants;AssetExportPublicationController controller;Publication p;
    @BeforeEach void setup()throws Exception{platform=mock(PlatformRepository.class);publications=mock(AssetExportPublicationRepository.class);store=mock(AssetExportObjectStore.class);grants=new AssetExportDownloadGrant(new byte[32]);controller=new AssetExportPublicationController(platform,publications,new AssetExportPublicationSupport(true,store,grants));when(platform.membership(actor,tenant)).thenReturn(Optional.of(new Membership(actor,tenant,"padmin",1,true)));when(platform.idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any())).thenAnswer(c->{((Runnable)c.getArgument(6)).run();return ((Supplier<?>)c.getArgument(7)).get();});String sha=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));p=new Publication(new Job(id,tenant,actor,1,"padmin","a".repeat(64),new Filters(null,null,null,null),State.SUCCEEDED,4,now.minusSeconds(30),now),new Encoding("b".repeat(64),sha,bytes.length,1,now.minusSeconds(20)),id,now,now);when(publications.publication(any(),eq(id))).thenReturn(p);when(publications.publicationInCommand(any(),eq(id))).thenReturn(p);when(store.read(p.objectKey(),bytes.length,sha)).thenReturn(bytes.clone());}
    MockHttpServletRequest request(String method,String suffix,String body){var r=new MockHttpServletRequest(method,"/api/v1/asset-export-jobs/"+id+suffix);r.setUserPrincipal(()->actor);r.getSession().setAttribute("mop.tenant_id",tenant);r.setAttribute("mop.trace_id","publication-test");r.addHeader("Idempotency-Key","publication-test-key");r.setContentType("application/json");r.setContent(body.getBytes(StandardCharsets.UTF_8));return r;}
    Map<?,?> data(Object x){return (Map<?,?>)((Map<?,?>)x).get("data");}
    String publishBody(){return "{\"expected_version\":2,\"file_sha256\":\""+p.prepared().fileSha256()+"\",\"action\":\"PUBLISH_PREPARED_FILE\"}";}
    MockHttpServletRequest download(){var r=request("GET","/content","");r.addParameter("grant",grants.issue(p.binding(),now).token());return r;}
    @Test void publicationHasExplicitIntentAndImmutableDescriptor(){when(publications.publish(any(),eq(id),eq(2L),eq(p.prepared().fileSha256()),any())).thenAnswer(c->{((VerifiedWriter)c.getArgument(4)).store(p.objectKey(),AssetExportPreparedFile.create(new Command(new AssetExportJobState.Access(UUID.fromString(tenant),UUID.fromString(actor),1,"padmin",true),new Filters(null,null,null,null)),"b".repeat(64),1,now.minusSeconds(20),bytes));return p;});var d=data(controller.publish(id,request("POST","/publication",publishBody())));assertEquals("PUBLISHED",d.get("status"));assertEquals(false,d.get("notification_sent"));verify(publications).authorizePublication(any(),eq(id));verify(store).storeImmutable(eq(p.objectKey()),any(),eq(p.prepared().fileSha256()));}
    @Test void malformedIntentVersionDuplicateFieldsAndScopeOverrideRejected(){for(String body:List.of("{}",publishBody().replace("PUBLISH_PREPARED_FILE","PREPARE_ONLY"),publishBody().replace("\"expected_version\":2","\"expected_version\":0"),publishBody().replace("\"expected_version\":2","\"expected_version\":2.0"),publishBody().replace("{","{\"tenant_id\":\"bad\","),publishBody()+" {}","{\"expected_version\":2,\"expected_version\":2}"))assertEquals(400,assertThrows(DomainException.class,()->controller.publish(id,request("POST","/publication",body))).status);verifyNoInteractions(publications,store);}
    @Test void missingIdempotencyKeyIsRejectedBeforeStorage(){var r=request("POST","/publication",publishBody());r.removeHeader("Idempotency-Key");assertEquals(400,assertThrows(DomainException.class,()->controller.publish(id,r)).status);verifyNoInteractions(store,publications);}
    @Test void preparationReceiptDoesNotImplicitlyAuthorizePublication(){var disabled=new AssetExportPublicationController(platform,publications,new AssetExportPublicationSupport(false,null,null));assertEquals(422,assertThrows(DomainException.class,()->disabled.publish(id,request("POST","/publication",publishBody()))).status);verifyNoInteractions(publications,store);}
    @Test void grantsAreSignedActorBoundAndAuditContainsNoToken(){var result=data(controller.grant(id,request("POST","/content-grants","{}")));String url=(String)result.get("content_url");assertTrue(url.startsWith("/api/v1/asset-export-jobs/"+id+"/content?grant="));grants.verify(p.binding(),url.substring(url.indexOf("grant=")+6),now);assertEquals(now.plusSeconds(900),result.get("expires_at"));verify(platform).audit(eq(actor),eq(tenant),eq("asset_export.content_grant"),eq("asset_export"),eq(id),eq("SUCCEEDED"),eq("ACTOR_TENANT_VERSION_BOUND_900_SECONDS"),eq("publication-test"));verifyNoInteractions(store);}
    @Test void downloadReadsActualBytesAndRechecksAfterStorage(){var response=controller.content(id,download());assertArrayEquals(bytes,response.getBody());assertTrue(response.getHeaders().getFirst("Content-Disposition").startsWith("attachment;"));assertEquals("no-store",response.getHeaders().getCacheControl());verify(publications,times(2)).publication(any(),eq(id));verify(platform).audit(eq(actor),eq(tenant),eq("asset_export.content_read"),any(),eq(id),any(),any(),any());}
    @Test void permissionChangeDuringObjectReadCannotReturnBytes(){when(publications.publication(any(),eq(id))).thenReturn(p).thenThrow(new DomainException(401,"SESSION_EXPIRED","changed"));assertEquals(401,assertThrows(DomainException.class,()->controller.content(id,download())).status);verify(platform,never()).audit(any(),any(),any(),any(),any(),any(),any(),any());}
    @Test void expiryDuringReadCannotReturnBytes(){when(publications.publication(any(),eq(id))).thenReturn(p).thenReturn(new Publication(p.job(),p.prepared(),id,p.storedAt(),now.plusSeconds(900)));assertEquals(404,assertThrows(DomainException.class,()->controller.content(id,download())).status);verify(platform,never()).audit(any(),any(),any(),any(),any(),any(),any(),any());}
    @Test void damagedBytesAreNotSent(){when(store.read(any(),anyLong(),any())).thenReturn(new byte[]{0});assertEquals(503,assertThrows(DomainException.class,()->controller.content(id,download())).status);}
    @Test void invalidOrDuplicateGrantRejectedBeforeStore(){var bad=download();bad.setParameter("grant","invalid");assertEquals(404,assertThrows(DomainException.class,()->controller.content(id,bad)).status);var duplicate=download();duplicate.addParameter("grant","another");assertEquals(400,assertThrows(DomainException.class,()->controller.content(id,duplicate)).status);verifyNoInteractions(store);}
    @Test void currentOwnerAndTenantCheckedBeforeDisplayingPublication(){var wrong=new Job(id,tenant,id,1,"padmin",p.job().inputSha256(),p.job().filters(),State.SUCCEEDED,4,p.job().createdAt(),p.job().updatedAt());when(publications.publication(any(),eq(id))).thenReturn(new Publication(wrong,p.prepared(),id,now,now));assertEquals(503,assertThrows(DomainException.class,()->controller.get(id,request("GET","/publication",""))).status);}
    @Test void customerAndInactiveMembershipRejected(){for(String role:List.of("viewer","tadmin")){when(platform.membership(actor,tenant)).thenReturn(Optional.of(new Membership(actor,tenant,role,1,true)));assertEquals(403,assertThrows(DomainException.class,()->controller.get(id,request("GET","/publication",""))).status);}when(platform.membership(actor,tenant)).thenReturn(Optional.of(new Membership(actor,tenant,"padmin",1,false)));assertEquals(401,assertThrows(DomainException.class,()->controller.get(id,request("GET","/publication",""))).status);verifyNoInteractions(publications,store);}
    @Test void explicitlyBadConfigurationFailsClosedWithoutFallback(){var configuration=new AssetExportPublicationConfiguration();assertEquals(false,configuration.assetExportPublicationSupport(new MockEnvironment()).status().get("enabled"));for(String flag:List.of("true","typo")){var support=configuration.assetExportPublicationSupport(new MockEnvironment().withProperty("MOP_EXPORT_PUBLICATION_ENABLED",flag));assertEquals(true,support.status().get("enabled"));assertEquals(false,support.status().get("ready"));assertEquals(503,assertThrows(DomainException.class,support::store).status);}}
}
